/**
 * Create a SharedArrayBuffer for thread synchronization.
 * Uses Int32 for Atomics compatibility.
 *
 * @returns {SharedArrayBuffer} The sync buffer
 */
export function createSyncBuffer(): SharedArrayBuffer;
/**
 * Create a typed view into the sync buffer.
 *
 * @param {SharedArrayBuffer} buffer - The sync buffer
 * @returns {Int32Array} Typed array view for Atomics operations
 */
export function createSyncView(buffer: SharedArrayBuffer): Int32Array;
/**
 * Acquire a lock (set flag to LOCKED).
 * Non-blocking - just sets the flag.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to acquire
 */
export function acquireLock(syncView: Int32Array, flagIndex: number): void;
/**
 * Release a lock (set flag to UNLOCKED) and notify waiting threads.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to release
 */
export function releaseLock(syncView: Int32Array, flagIndex: number): void;
/**
 * Check if a lock is currently held.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to check
 * @returns {boolean} True if locked
 */
export function isLocked(syncView: Int32Array, flagIndex: number): boolean;
/**
 * Wait for a lock to be released (blocking).
 * Uses Atomics.wait for efficient waiting without busy-loop.
 *
 * Note: Atomics.wait is only available in workers, not the main thread.
 * On the main thread, this falls back to checking the flag.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to wait on
 * @param {number} [timeout=LOCK_TIMEOUT_MS] - Maximum wait time in ms
 * @returns {string} 'ok' if unlocked, 'timed-out' if timeout reached, 'not-equal' if already unlocked
 */
export function waitForUnlock(syncView: Int32Array, flagIndex: number, timeout?: number): string;
/**
 * Wait for a lock to be released with async/await support.
 * This is for main thread use where Atomics.wait is not available.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to wait on
 * @param {number} [timeout=LOCK_TIMEOUT_MS] - Maximum wait time in ms
 * @returns {Promise<string>} 'ok' if unlocked, 'timed-out' if timeout reached
 */
export function waitForUnlockAsync(syncView: Int32Array, flagIndex: number, timeout?: number): Promise<string>;
/**
 * Execute a function while holding a lock.
 * Automatically releases the lock when done.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to lock
 * @param {Function} fn - Function to execute while holding lock
 * @returns {*} Return value of fn
 */
export function withLock(syncView: Int32Array, flagIndex: number, fn: Function): any;
/**
 * Wait for another thread's lock to be released, then execute.
 *
 * @param {Int32Array} syncView - The sync buffer view
 * @param {number} flagIndex - Which flag to wait on
 * @param {Function} fn - Function to execute after unlock
 * @param {number} [timeout=LOCK_TIMEOUT_MS] - Maximum wait time
 * @returns {*} Return value of fn, or undefined if timed out
 */
export function afterUnlock(syncView: Int32Array, flagIndex: number, fn: Function, timeout?: number): any;
export namespace SyncFlag {
    let CALCULATING_SUBSTEP: number;
    let READING_INPUTS: number;
    let FRONT_IS_READING: number;
    let PHYSIC_IS_WRITING: number;
    let FRONT_WRITING_TEMP: number;
    let PHYSIC_READING_TEMP: number;
}
/** Total number of sync flags */
export const SYNC_BUFFER_SIZE: 6;
/** Value indicating lock is free */
export const UNLOCKED: 0;
/** Value indicating lock is held */
export const LOCKED: 1;
